async function ensureFonts(){
  const specs=[];
  const families={'Inter':['Regular','Medium','SemiBold','Bold'],'Plus Jakarta Sans':['SemiBold','Bold']};
  for(const fam in families){ for(const w of families[fam]){ specs.push({family:fam, style:w}); } }
