function findComp(name){ return figma.root.findAll(n=>n.type==='COMPONENT' && n.name===name)[0]; }
async function ensureFonts(){
  const specs=[]; const families={'Inter':['Regular','Medium','SemiBold','Bold'],'Plus Jakarta Sans':['SemiBold','Bold']};
  for(const fam in families){ for(const w of families[fam]) specs.push({family:fam,style:w}); }
  try{ await Promise.all(specs.map(s=>figma.loadFontAsync(s))); }catch(e){}
}
function hex(h){ h=h.replace('#',''); return {r:parseInt(h.slice(0,2),16)/255,g:parseInt(h.slice(2,4),16)/255,b:parseInt(h.slice(4,6),16)/255}; }
async function text(parent,x,y,content,family,style,px,color,align){
  await figma.loadFontAsync({family:family,style:style});
  const t=figma.createText(); t.fontName={family:family,style:style}; t.fontSize=px; t.characters=content; t.x=x; t.y=y;
  t.fills=[{type:'SOLID',color:color?hex(color):{r:0,g:0,b:0}}]; t.textAlignHorizontal=align||'LEFT'; parent.appendChild(t); return t;
}
async function putInst(parent, name, x,y,w,h){
  const c=findComp(name); if(!c){ figma.notify('MISS '+name); return null; }
  const i=await figma.createInstanceFromNodeAsync(c); i.x=x; i.y=y; if(w&&h)i.resize(w,h); parent.appendChild(i); return i;
}
async function rect(parent,x,y,w,h,color,r,stroke){
  const f=figma.createRectangle(); f.x=x; f.y=y; f.resize(w,h); f.fills=[{type:'SOLID',color:hex(color)}];
  if(r)f.cornerRadius=r; if(stroke){f.strokes=[{type:'SOLID',color:hex(stroke)}];f.strokeWeight=1;} parent.appendChild(f); return f;
}

